Rather than rushing through problems, my focus is on understanding patterns, improving reasoning, and writing cleaner solutions over time.
Approach:
Key Learning:
pointer-based merging instead of relying purely on sorting.
class Solution {
public:
    vector<int> merge(vector<int>& nums1, int m, vector<int>& nums2, int n) {
        for(int i = m; i < m + n; i++) {
            nums1[i] = nums2[i - m];
        }
        for(int i = 0; i < m + n - 1; i++) {
            for(int j = 0; j < m + n - i - 1; j++) {
                if(nums1[j] > nums1[j+1]) {
                    swap(nums1[j], nums1[j+1]);
                }
            }
        }
        return nums1;
    }
};

Approach:
write pointer (idx) to overwrite unwanted values in-place.
Key Learning:
class Solution {
public:
    int removeElement(vector<int>& nums, int val) {
        int idx = 0;
        for(int i = 0; i < nums.size(); i++){
            if(nums[i] != val){
                nums[idx++] = nums[i];
            }
        }
        return idx;
    }
};

Approach:
Key Learning:
class Solution {
public:
    int removeDuplicates(vector<int>& nums) {
        if(nums.empty()) return 0;
        int idx = 1;
        for(int i = 1; i < nums.size(); i++) {
            if(nums[i] != nums[i-1]) {
                nums[idx++] = nums[i];
            }
        }
        return idx;
    }
};

